import java.util.Scanner;

public class Main {
    static final int MAXN = 60;
    static final long MOD = 1000000007L;

    static long n;
    static int k;

    static class Matrix {
        int n;
        int[][] a;

        Matrix(int size) {
            this.n = size;
            a = new int[n + 1][n + 1];
        }

        void init() {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    a[i][j] = 0;
                }
            }
        }

        void set() {
            init();
            for (int i = 1; i <= n; i++) {
                a[i][i] = 1;
            }
        }

        Matrix multiply(Matrix rhs) {
            Matrix ans = new Matrix(n);
            long[][] tmp = new long[n + 1][n + 1];
            final long MODLL = (long) MOD * MOD;

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    tmp[i][j] = 0;
                }
            }

            for (int i = 1; i <= n; i++) {
                for (int k = 1; k <= n; k++) {
                    for (int j = 1; j <= n; j++) {
                        tmp[i][j] += (long) a[i][k] * rhs.a[k][j];
                        if (tmp[i][j] >= MODLL) {
                            tmp[i][j] -= MODLL;
                        }
                    }
                }
            }

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    ans.a[i][j] = (int) (tmp[i][j] % MOD);
                }
            }
            return ans;
        }
    }

    static class Solver1 {
        static final int MAXN = 60;
        static final int MAXK = 50 + 10;

        static Matrix[][] f = new Matrix[MAXK][MAXN];
        static Matrix[][] sump = new Matrix[MAXK][MAXN];
        static Matrix[][] sums = new Matrix[MAXK][MAXN];

        static int[] num = new int[MAXK];
        static int cnt = 0;

        static int add(int x) {
            return x >= MOD ? x - (int) MOD : x;
        }

        static int sub(int x) {
            return x < 0 ? x + (int) MOD : x;
        }

        static int mul(int x, int y) {
            return (int) (((long) x * y) % MOD);
        }

        static void mainSolver() {
            cnt = 0;
            long tempN = n;
            while (tempN != 0) {
                num[++cnt] = (int) (tempN % k);
                tempN /= k;
            }

            for (int i = 0; i < k; i++) {
                f[0][i] = new Matrix(k + 1);
                f[0][i].n = k + 1;
                f[0][i].set();
                for (int j = 1; j <= k + 1; j++) {
                    f[0][i].a[j][j] = 1;
                    f[0][i].a[i + 1][j] = 1;
                }
            }

            // Initialize sums and sump for i=0
            sump[0][0] = new Matrix(k + 1);
            copyMatrix(sump[0][0], f[0][0]);
            sums[0][k - 1] = new Matrix(k + 1);
            copyMatrix(sums[0][k - 1], f[0][k - 1]);

            for (int i = 1; i < k; i++) {
                sump[0][i] = multiplyMatrices(f[0][i], sump[0][i - 1]);
            }

            for (int i = k - 2; i >= 0; i--) {
                sums[0][i] = multiplyMatrices(sums[0][i + 1], f[0][i]);
            }

            for (int i = 1; i < cnt; i++) {
                for (int j = 0; j < k; j++) {
                    if (j == 0) {
                        f[i][j] = sums[i - 1][j];
                    } else {
                        f[i][j] = multiplyMatrices(sump[i - 1][j - 1], sums[i - 1][j]);
                    }
                }

                // Update sump and sums for i
                sump[i][0] = f[i][0];
                sums[i][k - 1] = f[i][k - 1];

                for (int j = 1; j < k; j++) {
                    sump[i][j] = multiplyMatrices(f[i][j], sump[i][j - 1]);
                }

                for (int j = k - 2; j >= 0; j--) {
                    sums[i][j] = multiplyMatrices(sums[i][j + 1], f[i][j]);
                }
            }

            Matrix ans = new Matrix(k + 1);
            ans.n = k + 1;
            ans.set();

            int sumIndex = 0;
            for (int i = cnt; i >= 1; i--) {
                for (int j = 0; j < num[i]; j++) {
                    int index = (sumIndex + j) % k;
                    ans = multiplyMatrices(f[index][index], ans);
                }
                sumIndex += num[i];
                sumIndex %= k;
            }

            int res = 0;
            for (int i = 1; i <= k + 1; i++) {
                res = add(res + ans.a[i][k + 1]);
            }

            System.out.println(res);
        }

        static void copyMatrix(Matrix dest, Matrix src) {
            for (int i = 1; i <= src.n; i++) {
                for (int j = 1; j <= src.n; j++) {
                    dest.a[i][j] = src.a[i][j];
                }
            }
        }

        static Matrix multiplyMatrices(Matrix a, Matrix b) {
            return a.multiply(b);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextInt();

        Solver1.mainSolver();
        sc.close();
    }
}
